INSERT INTO posts VALUES('BysXXsCpOd5','https://www.instagram.com/p/BysXXsCpOd5/','06/14/2019 10:16:45am','image',742,0,'DeLand, Florida',1,unistr('Volunteer and Vietnam Veteran, Mike McGuire ( Mad Dog ) making up new hoses for the DC-3''s instrument panel, at our shop in DeLand Florida. Let''s keep him busy make a donation today to SAVE-A-DC-3 The Mr. Douglas Society Inc. 👇\u000awww.mrdouglas.org\u000a.\u000a.\u000a.\u000a.\u000a#volunteer #vietnam #veterans #notforprofit #donate #philanthropy #foundation #sponsor #sponsorshipopportunity #sponsored'),'097_06-14-2019');
