INSERT INTO posts VALUES('CI3dVuogQgj','https://www.instagram.com/p/CI3dVuogQgj/','12/16/2020 12:11:13pm','image',312,12,'',1,unistr('The Mr. Douglas Society would like to thank our Donors for there continued support during this pandemic. Now that a vaccine will soon be available, we will be ramping up to complete the restoration project. If everything goes well we should have Mister Douglas running this summer.\u000awww.mrdouglas.org\u000a.\u000a.\u000a.\u000a.\u000a.\u000a#aircraft #airplane #dc3 #pilot #taildragger #typerating #donor #philanthropy #philantrophy #giving #commercialpilot #fun #photooftheday #photography #aircraftrestoration'),'165_12-16-2020');
