INSERT INTO posts VALUES('Ca2ikywFBNd','https://www.instagram.com/p/Ca2ikywFBNd/','03/08/2022 1:02:50pm','carousel',90,2,'',2,unistr('Here are the overhauled auxiliary boost pumps! With a pic of how they looked when I sent them to Aircraft Accessories of Oklahoma, they have done a great job on them.\u000a.\u000a.\u000a.\u000a.\u000a.\u000a#fuel #fuelsystem #boeingcompany #fuelboostpump #pratwhitney #radialengine'),'215_03-08-2022');
