INSERT INTO posts VALUES('CcaU8LpOnjC','https://www.instagram.com/p/CcaU8LpOnjC/','04/16/2022 8:07:44am','image',283,2,'',1,unistr('Can''t think of a better way to spend a Good Friday! Completing the reassembly right engine propeller all ADs complied with. Should be good for 5 years.\u000amrdouglas.org\u000a.\u000a.\u000a.\u000a.\u000a.\u000a.\u000a#avationlovers #propeller #ads #dc3lovers #aircraftmaintenance'),'223_04-16-2022');
