PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE posts (
            shortcode TEXT PRIMARY KEY,
            url TEXT,
            date TEXT,
            type TEXT,
            likes INTEGER,
            comments_count INTEGER,
            location TEXT,
            items INTEGER,
            caption TEXT,
            folder_name TEXT
        );
CREATE TABLE comments (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            shortcode TEXT,
            comment_text TEXT,
            FOREIGN KEY(shortcode) REFERENCES posts(shortcode)
        );
COMMIT;
